function storedLanguage(){const saved=document.cookie.match(/(?:^|;\s*)codex_meter_language=(en|ko)(?:;|$)/)?.[1];return saved??(String(navigator.language??'').toLowerCase().startsWith('ko')?'ko':'en');}
let language=storedLanguage();
function t(key,values={}){const template=language==='ko'?(KOREAN[key]??key):key;return template.replace(/\{([a-z]+)\}/gi,(_match,name)=>String(values[name]??''));}
function applyDocumentLanguage(){document.documentElement.lang=language;const skip=document.querySelector('.skip');if(skip)skip.textContent=t('Skip to content');}
function setLanguage(next){language=next;document.cookie=`codex_meter_language=${language}; Path=/; Max-Age=31536000; SameSite=Strict${location.protocol==='https:'?'; Secure':''}`;applyDocumentLanguage();if(csrf)route();else renderLogin();}
function languageToggle(){const next=language==='en'?'ko':'en',label=next==='ko'?'한국어':'English';return el('button',{class:'language-toggle',type:'button','data-testid':'language-toggle','aria-label':t(next==='ko'?'Switch to Korean':'Switch to English'),text:label,onclick:()=>setLanguage(next)});}
class DisplayError extends Error{}const errorCopy=error=>error instanceof DisplayError?error.message:t('Unexpected Server response.');
const el=(tag,attrs={},...children)=>{const node=document.createElement(tag);for(const[key,value]of Object.entries(attrs)){if(key==='class')node.className=value;else if(key==='text')node.textContent=value;else if(key.startsWith('on'))node.addEventListener(key.slice(2).toLowerCase(),value);else if(value!==null&&value!==false)node.setAttribute(key,value===true?'':String(value));}for(const child of children.flat()){if(child!==null&&child!==undefined)node.append(child instanceof Node?child:document.createTextNode(String(child)));}return node;};
function clear(node=app){node.replaceChildren();}function notify(message){toast.textContent=message;toast.hidden=false;setTimeout(()=>{toast.hidden=true;},3500);}function fmt(value){try{return BigInt(value).toLocaleString(language==='ko'?'ko-KR':'en-US');}catch{return '—';}}function when(value){return value?new Date(value).toLocaleString(language==='ko'?'ko-KR':'en-US'):t('Never');}
async function api(path,options={}){const init={credentials:'same-origin',headers:{accept:'application/json'},...options};if(options.body!==undefined){init.headers={...init.headers,'content-type':'application/json','x-csrf-token':csrf};init.body=JSON.stringify(options.body);}let response;try{response=await fetch(`/api/v1${path}`,init);}catch{throw new DisplayError(t('The Server could not be reached.'));}let data={};try{data=await response.json();}catch{}if(response.status===401){csrf=null;renderLogin();throw new DisplayError(t('Your session expired.'));}if(!response.ok){const copies={invalid_account:'Select an active Account Profile.',invalid_mode:'Select how this Codex login is used.',binding_exists_or_mode_conflict:'That Account Profile is already tracked here, or this login option is already in use.',binding_identity_conflict:'The existing local assignment could not be resumed.',enrollment_expired:'This enrollment expired. Create a new device enrollment.'};throw new DisplayError(t(copies[data.error]??'The request could not be completed.'));}return data;}
