async function route(){if(pollTimer){clearTimeout(pollTimer);pollTimer=null;}if(!csrf){try{const session=await api('/auth/session');csrf=session.csrfToken;}catch{return;}}const parts=(location.hash.replace(/^#\/?/,'')||'overview').split('/').map(decodeURIComponent);if(parts[0]==='overview')return overview();if(parts[0]==='groups'&&parts[1])return groupDetail(parts[1]);if(parts[0]==='groups')return groups();if(parts[0]==='devices'&&parts[1]==='add')return addDevice();if(parts[0]==='devices'&&parts[1])return deviceDetail(parts[1]);if(parts[0]==='devices')return devices();if(parts[0]==='accounts'&&parts[1])return accountDetail(parts[1]);if(parts[0]==='accounts')return accounts();if(parts[0]==='settings')return settings();location.hash='#/overview';}
applyDocumentLanguage();window.addEventListener('hashchange',route);route();
